schema_source:
@classmethod def define_schema(cls) -> IO.Schema: return IO.Schema(node_id='BeebleSwitchXImageEdit', display_name='Beeble SwitchX Image Edit', category='partner/image/Beeble', description="Edit a single image with Beeble SwitchX. Switches anything in the scene (background, lighting, costume) while preserving the original subject's pixels. Provide a reference image and/or text prompt to describe the new look. Max ~2.77MP.", inputs=_common_inputs(source=IO.Image.Input('image'), video=False), outputs=[IO.Image.Output(display_name='image'), IO.Mask.Output(display_name='alpha', tooltip="The alpha matte Beeble used. Empty for 'fill' mode, which has no separate matte.")], hidden=[IO.Hidden.auth_token_comfy_org, IO.Hidden.api_key_comfy_org, IO.Hidden.unique_id], is_api_node=True, price_badge=IO.PriceBadge(depends_on=IO.PriceBadgeDepends(widgets=['max_resolution']), expr='
 (
 $rate := widgets.max_resolution = "1080p" ? 0.429 : 0.143;
 {"type":"usd","usd": $rate}
 )
 '))

@classmethod def define_schema(cls) -> IO.Schema: return IO.Schema(node_id='BeebleSwitchXVideoEdit', display_name='Beeble SwitchX Video Edit', category='partner/video/Beeble', description="Edit a video with Beeble SwitchX. Switches anything in the scene (background, lighting, costume) while preserving the original subject's pixels and motion. Provide a reference image and/or text prompt to describe the new look. Max 240 frames, max ~2.77MP per frame.", inputs=_common_inputs(source=IO.Video.Input('video'), video=True), outputs=[IO.Video.Output(display_name='video'), IO.Video.Output(display_name='alpha', tooltip="The alpha matte Beeble used. Empty for 'fill' mode, which has no separate matte.")], hidden=[IO.Hidden.auth_token_comfy_org, IO.Hidden.api_key_comfy_org, IO.Hidden.unique_id], is_api_node=True, price_badge=IO.PriceBadge(depends_on=IO.PriceBadgeDepends(widgets=['max_resolution']), expr='
 (
 $rate := widgets.max_resolution = "1080p" ? 0.429 : 0.143;
 {"type":"usd","usd": $rate, "format":{"suffix":"/30 frames"}}
 )
 '))

@classmethod def define_schema(cls): return IO.Schema(node_id='ByteDance2FirstLastFrameNode', display_name='ByteDance Seedance 2.0 First-Last-Frame to Video', category='partner/video/ByteDance', description='Generate video using Seedance 2.0 from a first frame image and optional last frame image.', inputs=[IO.DynamicCombo.Input('model', options=[IO.DynamicCombo.Option('Seedance 2.0', _seedance2_text_inputs(['480p', '720p', '1080p', '4k'], default_ratio='adaptive')), IO.DynamicCombo.Option('Seedance 2.0 Fast', _seedance2_text_inputs(['480p', '720p'], default_ratio='adaptive')), IO.DynamicCombo.Option('Seedance 2.0 Mini', _seedance2_text_inputs(['480p', '720p'], default_ratio='adaptive'))], tooltip='Seedance 2.0 for maximum quality; Fast for speed optimization; Mini for the fastest, lowest-cost generation.'), IO.Image.Input('first_frame', tooltip='First frame image for the video.', optional=True), IO.Image.Input('last_frame', tooltip='Last frame image for the video.', optional=True), IO.String.Input('first_frame_asset_id', default='', tooltip='Seedance asset_id to use as the first frame. Mutually exclusive with the first_frame image input.', optional=True), IO.String.Input('last_frame_asset_id', default='', tooltip='Seedance asset_id to use as the last frame. Mutually exclusive with the last_frame image input.', optional=True), IO.Int.Input('seed', default=0, min=0, max=2147483647, step=1, display_mode=IO.NumberDisplay.number, control_after_generate=True, tooltip='Seed controls whether the node should re-run; results are non-deterministic regardless of seed.'), IO.Boolean.Input('watermark', default=False, tooltip='Whether to add a watermark to the video.', advanced=True)], outputs=[IO.Video.Output()], hidden=[IO.Hidden.auth_token_comfy_org, IO.Hidden.api_key_comfy_org, IO.Hidden.unique_id], is_api_node=True, price_badge=IO.PriceBadge(depends_on=IO.PriceBadgeDepends(widgets=['model', 'model.resolution', 'model.duration']), expr='
 (
 $rate480 := 10044;
 $rate720 := 21600;
 $rate1080 := 48800;
 $rate4k := 195200;
 $m := widgets.model;
 $res := $lookup(widgets, "model.resolution");
 $dur := $lookup(widgets, "model.duration");
 $pricePer1K := $res = "4k" ? 0.00572 :
 $res = "1080p" ? 0.011011 :
 $contains($m, "mini") ? 0.005005 :
 $contains($m, "fast") ? 0.008008 : 0.01001;
 $rate := $res = "4k" ? $rate4k :
 $res = "1080p" ? $rate1080 :
 $res = "720p" ? $rate720 :
 $rate480;
 $cost := $dur * $rate * $pricePer1K / 1000;
 {"type": "usd", "usd": $cost, "format": {"approximate": true}}
 )
 '))

@classmethod def define_schema(cls): return IO.Schema(node_id='ByteDance2ReferenceNode', display_name='ByteDance Seedance 2.0 Reference to Video', category='partner/video/ByteDance', description='Generate, edit, or extend video using Seedance 2.0 with reference images, videos, and audio. Supports multimodal reference, video editing, and video extension.', inputs=[IO.DynamicCombo.Input('model', options=[IO.DynamicCombo.Option('Seedance 2.0', _seedance2_reference_inputs(['480p', '720p', '1080p', '4k'], default_ratio='adaptive')), IO.DynamicCombo.Option('Seedance 2.0 Fast', _seedance2_reference_inputs(['480p', '720p'], default_ratio='adaptive')), IO.DynamicCombo.Option('Seedance 2.0 Mini', _seedance2_reference_inputs(['480p', '720p'], default_ratio='adaptive'))], tooltip='Seedance 2.0 for maximum quality; Fast for speed optimization; Mini for the fastest, lowest-cost generation.'), IO.Int.Input('seed', default=0, min=0, max=2147483647, step=1, display_mode=IO.NumberDisplay.number, control_after_generate=True, tooltip='Seed controls whether the node should re-run; results are non-deterministic regardless of seed.'), IO.Boolean.Input('watermark', default=False, tooltip='Whether to add a watermark to the video.', advanced=True)], outputs=[IO.Video.Output()], hidden=[IO.Hidden.auth_token_comfy_org, IO.Hidden.api_key_comfy_org, IO.Hidden.unique_id], is_api_node=True, price_badge=IO.PriceBadge(depends_on=IO.PriceBadgeDepends(widgets=['model', 'model.resolution', 'model.duration'], input_groups=['model.reference_videos']), expr='
 (
 $rate480 := 10044;
 $rate720 := 21600;
 $rate1080 := 48800;
 $rate4k := 195200;
 $m := widgets.model;
 $hasVideo := $lookup(inputGroups, "model.reference_videos") > 0;
 $res := $lookup(widgets, "model.resolution");
 $dur := $lookup(widgets, "model.duration");
 $noVideoPricePer1K := $res = "4k" ? 0.00572 :
 $res = "1080p" ? 0.011011 :
 $contains($m, "mini") ? 0.005005 :
 $contains($m, "fast") ? 0.008008 : 0.01001;
 $videoPricePer1K := $res = "4k" ? 0.003432 :
 $res = "1080p" ? 0.006721 :
 $contains($m, "mini") ? 0.003003 :
 $contains($m, "fast") ? 0.004719 : 0.006149;
 $rate := $res = "4k" ? $rate4k :
 $res = "1080p" ? $rate1080 :
 $res = "720p" ? $rate720 :
 $rate480;
 $noVideoCost := $dur * $rate * $noVideoPricePer1K / 1000;
 $minVideoFactor := $ceil($dur * 5 / 3);
 $minVideoCost := $minVideoFactor * $rate * $videoPricePer1K / 1000;
 $maxVideoCost := (15 + $dur) * $rate * $videoPricePer1K / 1000;
 $hasVideo
 ? {
 "type": "range_usd",
 "min_usd": $minVideoCost,
 "max_usd": $maxVideoCost,
 "format": {"approximate": true}
 }
 : {
 "type": "usd",
 "usd": $noVideoCost,
 "format": {"approximate": true}
 }
 )
 '))

@classmethod def define_schema(cls): return IO.Schema(node_id='ByteDance2TextToVideoNode', display_name='ByteDance Seedance 2.0 Text to Video', category='partner/video/ByteDance', description='Generate video using Seedance 2.0 models based on a text prompt.', inputs=[IO.DynamicCombo.Input('model', options=[IO.DynamicCombo.Option('Seedance 2.0', _seedance2_text_inputs(['480p', '720p', '1080p', '4k'])), IO.DynamicCombo.Option('Seedance 2.0 Fast', _seedance2_text_inputs(['480p', '720p'])), IO.DynamicCombo.Option('Seedance 2.0 Mini', _seedance2_text_inputs(['480p', '720p']))], tooltip='Seedance 2.0 for maximum quality; Fast for speed optimization; Mini for the fastest, lowest-cost generation.'), IO.Int.Input('seed', default=0, min=0, max=2147483647, step=1, display_mode=IO.NumberDisplay.number, control_after_generate=True, tooltip='Seed controls whether the node should re-run; results are non-deterministic regardless of seed.'), IO.Boolean.Input('watermark', default=False, tooltip='Whether to add a watermark to the video.', advanced=True)], outputs=[IO.Video.Output()], hidden=[IO.Hidden.auth_token_comfy_org, IO.Hidden.api_key_comfy_org, IO.Hidden.unique_id], is_api_node=True, price_badge=IO.PriceBadge(depends_on=IO.PriceBadgeDepends(widgets=['model', 'model.resolution', 'model.duration']), expr='
 (
 $rate480 := 10044;
 $rate720 := 21600;
 $rate1080 := 48800;
 $rate4k := 195200;
 $m := widgets.model;
 $res := $lookup(widgets, "model.resolution");
 $dur := $lookup(widgets, "model.duration");
 $pricePer1K := $res = "4k" ? 0.00572 :
 $res = "1080p" ? 0.011011 :
 $contains($m, "mini") ? 0.005005 :
 $contains($m, "fast") ? 0.008008 : 0.01001;
 $rate := $res = "4k" ? $rate4k :
 $res = "1080p" ? $rate1080 :
 $res = "720p" ? $rate720 :
 $rate480;
 $cost := $dur * $rate * $pricePer1K / 1000;
 {"type": "usd", "usd": $cost, "format": {"approximate": true}}
 )
 '))

@classmethod def define_schema(cls): return IO.Schema(node_id='ByteDanceImageReferenceNode', display_name='ByteDance Reference Images to Video', category='partner/video/ByteDance', description='Generate video using prompt and reference images.', inputs=[IO.Combo.Input('model', options=['seedance-1-0-pro-250528', 'seedance-1-0-lite-i2v-250428'], default='seedance-1-0-lite-i2v-250428'), IO.String.Input('prompt', multiline=True, tooltip='The text prompt used to generate the video.'), IO.Image.Input('images', tooltip='One to four images.'), IO.Combo.Input('resolution', options=['480p', '720p'], tooltip='The resolution of the output video.'), IO.Combo.Input('aspect_ratio', options=['adaptive', '16:9', '4:3', '1:1', '3:4', '9:16', '21:9'], tooltip='The aspect ratio of the output video.'), IO.Int.Input('duration', default=5, min=3, max=12, step=1, tooltip='The duration of the output video in seconds.', display_mode=IO.NumberDisplay.slider), IO.Int.Input('seed', default=0, min=0, max=2147483647, step=1, display_mode=IO.NumberDisplay.number, control_after_generate=True, tooltip='Seed to use for generation.', optional=True), IO.Boolean.Input('watermark', default=False, tooltip='Whether to add an "AI generated" watermark to the video.', optional=True, advanced=True)], outputs=[IO.Video.Output()], hidden=[IO.Hidden.auth_token_comfy_org, IO.Hidden.api_key_comfy_org, IO.Hidden.unique_id], is_api_node=True, price_badge=IO.PriceBadge(depends_on=IO.PriceBadgeDepends(widgets=['model', 'duration', 'resolution']), expr='
 (
 $priceByModel := {
 "seedance-1-0-pro": {
 "480p":[0.23,0.24],
 "720p":[0.51,0.56]
 },
 "seedance-1-0-lite": {
 "480p":[0.17,0.18],
 "720p":[0.37,0.41]
 }
 };
 $model := widgets.model;
 $modelKey :=
 $contains($model, "seedance-1-0-pro") ? "seedance-1-0-pro" :
 "seedance-1-0-lite";
 $resolution := widgets.resolution;
 $resKey :=
 $contains($resolution, "720") ? "720p" :
 "480p";
 $modelPrices := $lookup($priceByModel, $modelKey);
 $baseRange := $lookup($modelPrices, $resKey);
 $min10s := $baseRange[0];
 $max10s := $baseRange[1];
 $scale := widgets.duration / 10;
 $minCost := $min10s * $scale;
 $maxCost := $max10s * $scale;
 ($minCost = $maxCost)
 ? {"type":"usd","usd": $minCost}
 : {"type":"range_usd","min_usd": $minCost, "max_usd": $maxCost}
 )
 '))

@classmethod def define_schema(cls): return IO.Schema(node_id='ByteDanceSeedNode', display_name='ByteDance Seed', category='partner/text/ByteDance', essentials_category='Text Generation', description="Generate text responses with ByteDance's Seed 2.0 models. Provide a text prompt and optionally one or more images or videos for multimodal context.", inputs=[IO.String.Input('prompt', multiline=True, default='', tooltip='Text input to the model.'), IO.DynamicCombo.Input('model', options=[IO.DynamicCombo.Option(label, _seed_model_inputs()) for label in SEED_MODELS], tooltip='The Seed model used to generate the response.'), IO.Int.Input('seed', default=0, min=0, max=2147483647, control_after_generate=True, tooltip='Seed controls whether the node should re-run; results are non-deterministic regardless of seed.'), IO.String.Input('system_prompt', multiline=True, default='', optional=True, advanced=True, tooltip="Foundational instructions that dictate the model's behavior.")], outputs=[IO.String.Output()], hidden=[IO.Hidden.auth_token_comfy_org, IO.Hidden.api_key_comfy_org, IO.Hidden.unique_id], is_api_node=True, price_badge=IO.PriceBadge(depends_on=IO.PriceBadgeDepends(widgets=['model']), expr='
 (
 $m := widgets.model;
 $contains($m, "mini") ? {
 "type": "list_usd",
 "usd": [0.00025, 0.0009],
 "format": { "approximate": true, "separator": "-", "suffix": " per 1K tokens" }
 }
 : $contains($m, "lite") ? {
 "type": "list_usd",
 "usd": [0.0003, 0.002],
 "format": { "approximate": true, "separator": "-", "suffix": " per 1K tokens" }
 }
 : $contains($m, "pro") ? {
 "type": "list_usd",
 "usd": [0.0005, 0.003],
 "format": { "approximate": true, "separator": "-", "suffix": " per 1K tokens" }
 }
 : {"type":"text", "text":"Token-based"}
 )
 '))

@classmethod def define_schema(cls): return IO.Schema(node_id='ByteDanceSeedreamNode', display_name='ByteDance Seedream 4.5 & 5.0', category='partner/image/ByteDance', description='Unified text-to-image generation and precise single-sentence editing at up to 4K resolution.', inputs=[IO.Combo.Input('model', options=list(SEEDREAM_MODELS.keys())), IO.String.Input('prompt', multiline=True, default='', tooltip='Text prompt for creating or editing an image.'), IO.Image.Input('image', tooltip='Input image(s) for image-to-image generation. Reference image(s) for single or multi-reference generation.', optional=True), IO.Combo.Input('size_preset', options=[label for (label, _, _) in RECOMMENDED_PRESETS_SEEDREAM_4], tooltip='Pick a recommended size. Select Custom to use the width and height below.'), IO.Int.Input('width', default=2048, min=1024, max=6240, step=2, tooltip='Custom width for image. Value is working only if `size_preset` is set to `Custom`', optional=True), IO.Int.Input('height', default=2048, min=1024, max=4992, step=2, tooltip='Custom height for image. Value is working only if `size_preset` is set to `Custom`', optional=True), IO.Combo.Input('sequential_image_generation', options=['disabled', 'auto'], tooltip="Group image generation mode. 'disabled' generates a single image. 'auto' lets the model decide whether to generate multiple related images (e.g., story scenes, character variations).", optional=True), IO.Int.Input('max_images', default=1, min=1, max=15, step=1, display_mode=IO.NumberDisplay.number, tooltip="Maximum number of images to generate when sequential_image_generation='auto'. Total images (input + generated) cannot exceed 15.", optional=True), IO.Int.Input('seed', default=0, min=0, max=2147483647, step=1, display_mode=IO.NumberDisplay.number, control_after_generate=True, tooltip='Seed to use for generation.', optional=True), IO.Boolean.Input('watermark', default=False, tooltip='Whether to add an "AI generated" watermark to the image.', optional=True, advanced=True), IO.Boolean.Input('fail_on_partial', default=True, tooltip='If enabled, abort execution if any requested images are missing or return an error.', optional=True, advanced=True)], outputs=[IO.Image.Output()], hidden=[IO.Hidden.auth_token_comfy_org, IO.Hidden.api_key_comfy_org, IO.Hidden.unique_id], is_api_node=True, price_badge=IO.PriceBadge(depends_on=IO.PriceBadgeDepends(widgets=['model']), expr='
 (
 $price := $contains(widgets.model, "5.0 lite") ? 0.035 :
 $contains(widgets.model, "4-5") ? 0.04 : 0.03;
 {
 "type":"usd",
 "usd": $price,
 "format": { "suffix":" x images/Run", "approximate": true }
 }
 )
 '), is_deprecated=True)

@classmethod def define_schema(cls): return IO.Schema(node_id='ByteDanceSeedreamNodeV2', display_name='ByteDance Seedream 4.5 & 5.0', category='partner/image/ByteDance', description='Unified text-to-image generation and precise single-sentence editing at up to 4K resolution.', inputs=[IO.String.Input('prompt', multiline=True, default='', tooltip='Text prompt for creating or editing an image.'), IO.DynamicCombo.Input('model', options=[IO.DynamicCombo.Option('seedream 5.0 pro', _seedream_model_inputs(max_ref_images=10, presets=RECOMMENDED_PRESETS_SEEDREAM_5_PRO, max_width=3136, max_height=2496, supports_batch=False)), IO.DynamicCombo.Option('seedream 5.0 lite', _seedream_model_inputs(max_ref_images=14, presets=RECOMMENDED_PRESETS_SEEDREAM_5_LITE)), IO.DynamicCombo.Option('seedream-4-5-251128', _seedream_model_inputs(max_ref_images=10, presets=RECOMMENDED_PRESETS_SEEDREAM_4_5)), IO.DynamicCombo.Option('seedream-4-0-250828', _seedream_model_inputs(max_ref_images=10, presets=RECOMMENDED_PRESETS_SEEDREAM_4_0))]), IO.Int.Input('seed', default=0, min=0, max=2147483647, step=1, display_mode=IO.NumberDisplay.number, control_after_generate=True, tooltip='Seed to use for generation.'), IO.Boolean.Input('watermark', default=False, tooltip='Whether to add an "AI generated" watermark to the image.', advanced=True)], outputs=[IO.Image.Output()], hidden=[IO.Hidden.auth_token_comfy_org, IO.Hidden.api_key_comfy_org, IO.Hidden.unique_id], is_api_node=True, price_badge=IO.PriceBadge(depends_on=IO.PriceBadgeDepends(widgets=['model', 'model.size_preset', 'model.width', 'model.height']), expr='
 (
 $sp := $lookup(widgets, "model.size_preset");
 $px := $lookup(widgets, "model.width") * $lookup(widgets, "model.height");
 $isPro := $contains(widgets.model, "5.0 pro");
 $price := $isPro
 ? (
 $contains($sp, "custom")
 ? ($px <= 2360000 ? 0.045 : 0.09)
 : ($contains($sp, "1k") ? 0.045 : 0.09)
 )
 : $contains(widgets.model, "5.0 lite") ? 0.035
 : $contains(widgets.model, "4-5") ? 0.04
 : 0.03;
 {
 "type": "usd",
 "usd": $price,
 "format": { "suffix": $isPro ? "/Image" : " x images/Run", "approximate": true }
 }
 )
 '))

@classmethod def define_schema(cls): return IO.Schema(node_id='ClaudeNode', display_name='Anthropic Claude', category='partner/text/Anthropic', essentials_category='Text Generation', description="Generate text responses with Anthropic's Claude models. Provide a text prompt and optionally one or more images for multimodal context.", inputs=[IO.String.Input('prompt', multiline=True, default='', tooltip='Text input to the model.'), IO.DynamicCombo.Input('model', options=[IO.DynamicCombo.Option(label, _claude_model_inputs(label)) for label in CLAUDE_MODELS], tooltip='The Claude model used to generate the response.'), IO.Int.Input('seed', default=0, min=0, max=2147483647, control_after_generate=True, tooltip='Seed controls whether the node should re-run; results are non-deterministic regardless of seed.'), IO.Autogrow.Input('images', template=IO.Autogrow.TemplateNames(IO.Image.Input('image'), names=[f'image_{i}' for i in range(1, CLAUDE_MAX_IMAGES + 1)], min=0), tooltip=f'Optional image(s) to use as context for the model. Up to {CLAUDE_MAX_IMAGES} images.'), IO.String.Input('system_prompt', multiline=True, default='', optional=True, advanced=True, tooltip="Foundational instructions that dictate the model's behavior.")], outputs=[IO.String.Output()], hidden=[IO.Hidden.auth_token_comfy_org, IO.Hidden.api_key_comfy_org, IO.Hidden.unique_id], is_api_node=True, price_badge=IO.PriceBadge(depends_on=IO.PriceBadgeDepends(widgets=['model']), expr='
 (
 $m := widgets.model;
 $contains($m, "opus") ? {
 "type": "list_usd",
 "usd": [0.005, 0.025],
 "format": { "approximate": true, "separator": "-", "suffix": " per 1K tokens" }
 }
 : $contains($m, "sonnet") ? {
 "type": "list_usd",
 "usd": [0.003, 0.015],
 "format": { "approximate": true, "separator": "-", "suffix": " per 1K tokens" }
 }
 : $contains($m, "haiku") ? {
 "type": "list_usd",
 "usd": [0.001, 0.005],
 "format": { "approximate": true, "separator": "-", "suffix": " per 1K tokens" }
 }
 : {"type":"text", "text":"Token-based"}
 )
 '))

@classmethod def define_schema(cls) -> IO.Schema: return IO.Schema(node_id='Flux2ImageNode', display_name='Flux.2 Image', category='partner/image/BFL', description='Generate images via Flux.2 [pro] or Flux.2 [max] from a prompt and optional reference images.', inputs=[IO.String.Input('prompt', multiline=True, default='', tooltip='Prompt for the image generation or edit'), IO.DynamicCombo.Input('model', options=[IO.DynamicCombo.Option('Flux.2 [pro]', _flux2_model_inputs()), IO.DynamicCombo.Option('Flux.2 [max]', _flux2_model_inputs())]), IO.Int.Input('seed', default=0, min=0, max=18446744073709551615, control_after_generate=True, tooltip='The random seed used for creating the noise.')], outputs=[IO.Image.Output()], hidden=[IO.Hidden.auth_token_comfy_org, IO.Hidden.api_key_comfy_org, IO.Hidden.unique_id], is_api_node=True, price_badge=IO.PriceBadge(depends_on=IO.PriceBadgeDepends(widgets=['model', 'model.width', 'model.height'], input_groups=['model.images']), expr='
 (
 $isMax := widgets.model = "flux.2 [max]";
 $MP := 1024 * 1024;
 $w := $lookup(widgets, "model.width");
 $h := $lookup(widgets, "model.height");
 $outMP := $max([1, $floor((($w * $h) + $MP - 1) / $MP)]);
 $outputCost := $isMax
 ? (0.07 + 0.03 * ($outMP - 1))
 : (0.03 + 0.015 * ($outMP - 1));
 $refMin := $isMax ? 0.03 : 0.015;
 $refMax := $isMax ? 0.24 : 0.12;
 $hasRefs := $lookup(inputGroups, "model.images") > 0;
 $hasRefs
 ? {
 "type": "range_usd",
 "min_usd": $outputCost + $refMin,
 "max_usd": $outputCost + $refMax,
 "format": { "approximate": true }
 }
 : {"type": "usd", "usd": $outputCost}
 )
 '))

@classmethod def define_schema(cls): return IO.Schema(node_id='GeminiNanoBanana2V2', display_name='Nano Banana 2', category='partner/image/Gemini', description='Generate or edit images synchronously via Google Vertex API.', inputs=[IO.String.Input('prompt', multiline=True, tooltip='Text prompt describing the image to generate or the edits to apply. Include any constraints, styles, or details the model should follow.', default=''), IO.DynamicCombo.Input('model', options=[IO.DynamicCombo.Option('Nano Banana 2 (Gemini 3.1 Flash Image)', _nano_banana_2_v2_model_inputs(resolutions=['1K', '2K', '4K'])), IO.DynamicCombo.Option('Nano Banana 2 Lite', _nano_banana_2_v2_model_inputs(resolutions=['1K']))]), IO.Int.Input('seed', default=42, min=0, max=18446744073709551615, control_after_generate=True, tooltip="When the seed is fixed to a specific value, the model makes a best effort to provide the same response for repeated requests. Deterministic output isn't guaranteed. Also, changing the model or parameter settings, such as the temperature, can cause variations in the response even when you use the same seed value. By default, a random seed value is used."), IO.Combo.Input('response_modalities', options=['IMAGE', 'IMAGE+TEXT'], advanced=True), IO.String.Input('system_prompt', multiline=True, default=GEMINI_IMAGE_SYS_PROMPT, optional=True, tooltip="Foundational instructions that dictate an AI's behavior.", advanced=True), IO.Float.Input('temperature', default=1.0, min=0.0, max=2.0, step=0.01, optional=True, tooltip='Controls randomness in generation. Lower is more focused/deterministic.', advanced=True), IO.Float.Input('top_p', default=0.95, min=0.0, max=1.0, step=0.01, optional=True, tooltip='Nucleus sampling threshold. Lower is more focused, higher more diverse.', advanced=True)], outputs=[IO.Image.Output(), IO.String.Output(), IO.Image.Output(display_name='thought_image', tooltip="First image from the model's thinking process. Only available with thinking_level HIGH and IMAGE+TEXT modality.")], hidden=[IO.Hidden.auth_token_comfy_org, IO.Hidden.api_key_comfy_org, IO.Hidden.unique_id], is_api_node=True, price_badge=IO.PriceBadge(depends_on=IO.PriceBadgeDepends(widgets=['model', 'model.resolution']), expr='
