@classmethod def define_schema(cls) -> IO.Schema: return IO.Schema(node_id='KlingVideoNode', display_name='Kling 3.0 Video', category='partner/video/Kling', description='Generate videos with Kling V3. Supports text-to-video and image-to-video with optional storyboard multi-prompt and audio generation.', inputs=[IO.DynamicCombo.Input('multi_shot', options=[IO.DynamicCombo.Option('disabled', [IO.String.Input('prompt', multiline=True, default=''), IO.String.Input('negative_prompt', multiline=True, default=''), IO.Int.Input('duration', default=5, min=3, max=15, display_mode=IO.NumberDisplay.slider)]), IO.DynamicCombo.Option('1 storyboard', _generate_storyboard_inputs(1)), IO.DynamicCombo.Option('2 storyboards', _generate_storyboard_inputs(2)), IO.DynamicCombo.Option('3 storyboards', _generate_storyboard_inputs(3)), IO.DynamicCombo.Option('4 storyboards', _generate_storyboard_inputs(4)), IO.DynamicCombo.Option('5 storyboards', _generate_storyboard_inputs(5)), IO.DynamicCombo.Option('6 storyboards', _generate_storyboard_inputs(6))], tooltip='Generate a series of video segments with individual prompts and durations.'), IO.Boolean.Input('generate_audio', default=True, tooltip="'kling-3.0-turbo' always generates native audio, so the audio toggle is ignored."), IO.DynamicCombo.Input('model', options=[IO.DynamicCombo.Option('kling-v3', [IO.Combo.Input('resolution', options=['4k', '1080p', '720p'], default='1080p'), IO.Combo.Input('aspect_ratio', options=['16:9', '9:16', '1:1'], tooltip='Ignored in image-to-video mode.')]), IO.DynamicCombo.Option('kling-3.0-turbo', [IO.Combo.Input('resolution', options=['1080p', '720p'], default='720p'), IO.Combo.Input('aspect_ratio', options=['16:9', '9:16', '1:1'], tooltip='Ignored in image-to-video mode.')])], tooltip='Model and generation settings.'), IO.Int.Input('seed', default=0, min=0, max=2147483647, display_mode=IO.NumberDisplay.number, control_after_generate=True, tooltip='Seed controls whether the node should re-run; results are non-deterministic regardless of seed.'), IO.Image.Input('start_frame', optional=True, tooltip='Optional start frame image. When connected, switches to image-to-video mode.')], outputs=[IO.Video.Output()], hidden=[IO.Hidden.auth_token_comfy_org, IO.Hidden.api_key_comfy_org, IO.Hidden.unique_id], is_api_node=True, price_badge=IO.PriceBadge(depends_on=IO.PriceBadgeDepends(widgets=['model', 'model.resolution', 'generate_audio', 'multi_shot', 'multi_shot.duration', 'multi_shot.storyboard_1_duration', 'multi_shot.storyboard_2_duration', 'multi_shot.storyboard_3_duration', 'multi_shot.storyboard_4_duration', 'multi_shot.storyboard_5_duration', 'multi_shot.storyboard_6_duration']), expr='
 (
 $res := $lookup(widgets, "model.resolution");
 $ms := widgets.multi_shot;
 $isSb := $ms != "disabled";
 $n := $isSb ? $number($substring($ms, 0, 1)) : 0;
 $d1 := $lookup(widgets, "multi_shot.storyboard_1_duration");
 $d2 := $n >= 2 ? $lookup(widgets, "multi_shot.storyboard_2_duration") : 0;
 $d3 := $n >= 3 ? $lookup(widgets, "multi_shot.storyboard_3_duration") : 0;
 $d4 := $n >= 4 ? $lookup(widgets, "multi_shot.storyboard_4_duration") : 0;
 $d5 := $n >= 5 ? $lookup(widgets, "multi_shot.storyboard_5_duration") : 0;
 $d6 := $n >= 6 ? $lookup(widgets, "multi_shot.storyboard_6_duration") : 0;
 $dur := $isSb ? $d1 + $d2 + $d3 + $d4 + $d5 + $d6 : $lookup(widgets, "multi_shot.duration");
 widgets.model = "kling-3.0-turbo"
 ? {"type":"usd","usd": ($res = "1080p" ? 0.14 : 0.112) * $dur}
 : (
 $rates := {
 "4k": {"off": 0.42, "on": 0.42},
 "1080p": {"off": 0.112, "on": 0.168},
 "720p": {"off": 0.084, "on": 0.126}
 };
 $audio := widgets.generate_audio ? "on" : "off";
 $rate := $lookup($lookup($rates, $res), $audio);
 {"type":"usd","usd": $rate * $dur}
 )
 )
 '))

@classmethod def define_schema(cls) -> IO.Schema: return IO.Schema(node_id='Krea2ImageNode', display_name='Krea 2 Image', category='partner/image/Krea', description='Generate images via Krea 2 — pick Medium (expressive illustrations) or Large (expressive photorealism). Supports an optional moodboard and up to 10 chained image style references.', inputs=[IO.String.Input('prompt', multiline=True, default='', tooltip='Text prompt for the image.'), IO.DynamicCombo.Input('model', options=[IO.DynamicCombo.Option(_MODEL_MEDIUM, _krea_model_inputs()), IO.DynamicCombo.Option(_MODEL_MEDIUM_TURBO, _krea_model_inputs()), IO.DynamicCombo.Option(_MODEL_LARGE, _krea_model_inputs())], tooltip='Krea 2 Medium is best for expressive illustrations; Krea 2 Large is best for expressive photorealism.'), IO.Int.Input('seed', default=0, min=0, max=2147483647, control_after_generate=True, tooltip='Random seed for reproducibility.')], outputs=[IO.Image.Output()], hidden=[IO.Hidden.auth_token_comfy_org, IO.Hidden.api_key_comfy_org, IO.Hidden.unique_id], is_api_node=True, price_badge=IO.PriceBadge(depends_on=IO.PriceBadgeDepends(widgets=['model', 'model.moodboard_id'], inputs=['model.style_reference']), expr='
 (
