ode=IO.NumberDisplay.number, tooltip='Output frame rate.'), IO.Int.Input('interpolation_slowmo', default=1, min=1, max=16, display_mode=IO.NumberDisplay.number, tooltip='Slow-motion factor applied to the input video. For example, 2 makes the output twice as slow and doubles the duration.', advanced=True), IO.Boolean.Input('interpolation_duplicate', default=False, tooltip='Analyze the input for duplicate frames and remove them.', advanced=True), IO.Float.Input('interpolation_duplicate_threshold', default=0.01, min=0.001, max=0.1, step=0.001, display_mode=IO.NumberDisplay.number, tooltip='Detection sensitivity for duplicate frames.', advanced=True)])]), IO.Combo.Input('dynamic_compression_level', options=['Low', 'Mid', 'High'], default='Low', tooltip='CQP level.', optional=True)], outputs=[IO.Video.Output()], hidden=[IO.Hidden.auth_token_comfy_org, IO.Hidden.api_key_comfy_org, IO.Hidden.unique_id], is_api_node=True, price_badge=IO.PriceBadge(depends_on=IO.PriceBadgeDepends(widgets=['upscaler_model', 'upscaler_model.upscaler_resolution', 'interpolation_model']), expr='
 (
 $model := $lookup(widgets, "upscaler_model");
 $res := $lookup(widgets, "upscaler_model.upscaler_resolution");
 $interp := $lookup(widgets, "interpolation_model");
 $is4k := $contains($res, "4k");
 $hasInterp := $interp != "disabled";
 $rates := {
 "starlight (astra) fast": {"hd": 0.43, "uhd": 0.85},
 "starlight precise 2.5": {"hd": 0.70, "uhd": 1.54},
 "astra 2": {"hd": 1.72, "uhd": 2.85},
 "starlight (astra) creative": {"hd": 2.25, "uhd": 3.99}
 };
 $surcharge := $is4k ? 0.28 : 0.14;
 $entry := $lookup($rates, $model);
 $base := $is4k ? $entry.uhd : $entry.hd;
 $hi := $base + ($hasInterp ? $surcharge : 0);
 $model = "disabled"
 ? {"type":"text","text":"Interpolation only"}
 : ($hasInterp
 ? {"type":"text","text":"~" & $string($base) & "–" & $string($hi) & " credits/src frame"}
 : {"type":"text","text":"~" & $string($base) & " credits/src frame"})
 )
 '))

