, is_api_node=True, is_output_node=True, price_badge=IO.PriceBadge(depends_on=IO.PriceBadgeDepends(widgets=['quad', 'face_limit', 'texture_size', 'texture_format', 'flatten_bottom', 'flatten_bottom_threshold', 'pivot_to_center_bottom', 'scale_factor']), expr='
 (
