@classmethod def define_schema(cls): return IO.Schema(node_id='TripoImageToModelNode', display_name='Tripo: Image to Model', category='partner/3d/Tripo', inputs=[IO.Image.Input('image'), IO.Combo.Input('model_version', options=TripoModelVersion, tooltip='The model version to use for generation', optional=True), IO.Combo.Input('style', options=TripoStyle, default='None', optional=True), IO.Boolean.Input('texture', default=True, optional=True), IO.Boolean.Input('pbr', default=True, optional=True), IO.Int.Input('model_seed', default=42, optional=True, advanced=True), IO.Combo.Input('orientation', options=TripoOrientation, default=TripoOrientation.DEFAULT, optional=True, advanced=True), IO.Int.Input('texture_seed', default=42, optional=True, advanced=True), IO.Combo.Input('texture_quality', default='standard', options=['standard', 'detailed'], optional=True, advanced=True), IO.Combo.Input('texture_alignment', default='original_image', options=['original_image', 'geometry'], optional=True, advanced=True), IO.Int.Input('face_limit', default=-1, min=-1, max=500000, optional=True, advanced=True), IO.Boolean.Input('quad', default=False, optional=True, advanced=True), IO.Combo.Input('geometry_quality', default='standard', options=['standard', 'detailed'], optional=True, advanced=True)], outputs=[IO.String.Output(display_name='model_file'), IO.Custom('MODEL_TASK_ID').Output(display_name='model task_id'), IO.File3DGLB.Output(display_name='GLB')], hidden=[IO.Hidden.auth_token_comfy_org, IO.Hidden.api_key_comfy_org, IO.Hidden.unique_id], is_api_node=True, is_output_node=True, price_badge=IO.PriceBadge(depends_on=IO.PriceBadgeDepends(widgets=['model_version', 'texture', 'pbr', 'quad', 'texture_quality', 'geometry_quality']), expr='
