den.api_key_comfy_org, IO.Hidden.unique_id], is_api_node=True, price_badge=IO.PriceBadge(depends_on=IO.PriceBadgeDepends(widgets=['model', 'generate_audio', 'resolution', 'duration_seconds']), expr='
