@classmethod def define_schema(cls): return IO.Schema(node_id='Vidu2ImageToVideoNode', display_name='Vidu2 Image-to-Video Generation', category='partner/video/Vidu', description='Generate a video from an image and an optional prompt.', inputs=[IO.Combo.Input('model', options=['viduq2-pro-fast', 'viduq2-pro', 'viduq2-turbo']), IO.Image.Input('image', tooltip='An image to be used as the start frame of the generated video.'), IO.String.Input('prompt', multiline=True, default='', tooltip='An optional text prompt for video generation (max 2000 characters).'), IO.Int.Input('duration', default=5, min=1, max=10, step=1, display_mode=IO.NumberDisplay.slider), IO.Int.Input('seed', default=1, min=0, max=2147483647, step=1, display_mode=IO.NumberDisplay.number, control_after_generate=True), IO.Combo.Input('resolution', options=['720p', '1080p'], advanced=True), IO.Combo.Input('movement_amplitude', options=['auto', 'small', 'medium', 'large'], tooltip='The movement amplitude of objects in the frame.', advanced=True)], outputs=[IO.Video.Output()], hidden=[IO.Hidden.auth_token_comfy_org, IO.Hidden.api_key_comfy_org, IO.Hidden.unique_id], is_api_node=True, price_badge=IO.PriceBadge(depends_on=IO.PriceBadgeDepends(widgets=['model', 'duration', 'resolution']), expr='
 (
 $m := widgets.model;
 $d := widgets.duration;
 $is1080 := widgets.resolution = "1080p";
 $contains($m, "pro-fast")
 ? (
 $base := $is1080 ? 0.08 : 0.04;
 $perSec := $is1080 ? 0.02 : 0.01;
 {"type":"usd","usd": $base + $perSec * ($d - 1)}
 )
 : $contains($m, "pro")
 ? (
 $base := $is1080 ? 0.275 : 0.075;
 $perSec := $is1080 ? 0.075 : 0.05;
 {"type":"usd","usd": $base + $perSec * ($d - 1)}
 )
 : $contains($m, "turbo")
 ? (
 $is1080
 ? {"type":"usd","usd": 0.175 + 0.05 * ($d - 1)}
 : (
 $d <= 1 ? {"type":"usd","usd": 0.04}
 : $d <= 2 ? {"type":"usd","usd": 0.05}
 : {"type":"usd","usd": 0.05 + 0.05 * ($d - 2)}
 )
 )
 : {"type":"usd","usd": 0.04}
 )
 '))

